<script setup>
import AccountSelect from '../components/AccountSelect.vue';
import {ref,computed,watch,onUnmounted,onDeactivated} from 'vue';import DateInput from '../components/DateInput.vue';import BaseModal from '../components/BaseModal.vue';import {state,api,scope,useResource,notify} from '../lib/workspace';
import {can,allowedApi} from '../lib/workspace';import {money,date,statusLabel} from '../lib/format';
import ReportPdfPreview from '../components/ReportPdfPreview.vue';
import {latestRequest,reportKindsForArea,reportFileUrl} from '../lib/report-state';
const props=defineProps({area:{type:String,default:'accounting'}});
const allKinds={diary:'Diário Geral','consolidated-diary':'Diário Consolidado',ledger:'Razão','trial-balance':'Balancete','cost-centers':'Movimentos por centro de custo','balance-sheet':'Balanço patrimonial','income-statement':'Demonstração do resultado','fiscal-book':'Livro auxiliar fiscal','fiscal-documents':'Documentos fiscais','fiscal-entries':'Livro auxiliar de entradas','fiscal-outputs':'Livro auxiliar de saídas','fiscal-items':'Itens escriturados','fiscal-operations':'Operações por CFOP','fiscal-participants':'Operações por participante','fiscal-classifications':'Itens por NCM e CFOP','fiscal-taxes':'Bases e tributos declarados','fiscal-inconsistencies':'Pendências de conferência','fiscal-assessments':'Livro auxiliar de apuração',financial:'Títulos por vencimento','cash-flow':'Caixa realizado',partners:'Conciliação de clientes e fornecedores'};
const kinds=computed(()=>reportKindsForArea(allKinds,props.area));
const routine=computed(()=>props.area+'.reports');
const preview=ref(false), requests=latestRequest(), origins=latestRequest();
const cfop=ref(''),ncm=ref(''),model=ref('internal'),firstPage=ref(1),showNumbers=ref(false);
const {data:models}=useResource(()=>state.companyId?api(scope('/report-models?module='+props.area)):Promise.resolve([]));
const kind=ref(props.area==='fiscal'?'fiscal-documents':props.area==='financial'?'financial':'trial-balance'),start=ref(''),end=ref(''),account=ref(''),center=ref(''),query=ref(''),status=ref(''),direction=ref(''),page=ref(1),result=ref(null),busy=ref(false),error=ref(''),origin=ref(null);
const selectedModels=computed(()=>(models.value||[]).filter(m=>m.kind===kind.value&&m.supported!==false));
const selectedModel=computed(()=>selectedModels.value.find(m=>m.id===model.value));
const areaModels=computed(()=>(models.value||[]).filter(m=>m.kind in kinds.value));
function invalidate(){requests.invalidate();origins.invalidate();busy.value=false;result.value=null;origin.value=null;preview.value=false;error.value='';page.value=1;}
onUnmounted(invalidate);onDeactivated(invalidate);
const {data}=useResource(async()=>{if(!state.companyId)return {accounts:[],centers:[]};const [accounts,centers]=await Promise.all([allowedApi('accounting.accounts',scope('/accounts')),allowedApi('accounting.cost_centers',scope('/cost-centers'))]);return {accounts,centers};},{accounts:[],centers:[]});
watch(()=>[state.companyId,state.period,props.area],()=>{invalidate();model.value='internal';status.value='';direction.value='';query.value='';showNumbers.value=false;kind.value=props.area==='fiscal'?'fiscal-documents':props.area==='financial'?'financial':'trial-balance';cfop.value='';ncm.value='';firstPage.value=1;account.value='';center.value='';start.value=state.period.slice(0,4)+'-01-01';end.value=state.period.slice(0,4)+'-12-31';},{immediate:true});
const accounting=computed(()=>['diary','consolidated-diary','ledger','trial-balance','cost-centers','balance-sheet','income-statement'].includes(kind.value));
const searchable=computed(()=>kind.value.startsWith('fiscal-')&&kind.value!=='fiscal-assessments'||['diary','ledger','fiscal-book','financial','cash-flow','partners'].includes(kind.value));
const fixedBook=computed(()=>['fiscal-entries','fiscal-outputs'].includes(kind.value));
const statuses=computed(()=>kind.value==='fiscal-assessments'||fixedBook.value?[]:kind.value.startsWith('fiscal-')?['pending','reviewed','booked']:['financial','partners'].includes(kind.value)?['open','partial','settled','cancelled','renegotiated']:[]);
const originRecord=computed(()=>origin.value?.data?.document&&typeof origin.value.data.document==='object'?origin.value.data.document:origin.value?.data);
watch(kind,()=>{invalidate();model.value='internal';firstPage.value=1;showNumbers.value=false;cfop.value='';ncm.value='';status.value='';direction.value='';query.value='';account.value='';center.value='';});
const labels={item:'Item',ncm:'NCM',unit:'Unidade',quantity:'Quantidade',item_total_cents:'Total dos itens',ledger_id:'Apuração',assessment_id:'Memória',period:'Competência',tax:'Tributo',opening_credit_cents:'Crédito anterior',payable_cents:'A recolher',carry_credit_cents:'Crédito a transportar',message:'Diagnóstico',code:'Código',document_ids:'Documentos de origem',items:'Itens',occurrences:'Ocorrências',date:'Data',journal_id:'Lançamento',number:'Número',document:'Documento',history:'Histórico',account_id:'Conta ID',access_code:'Acesso',classifier:'Classificação',account_name:'Conta',nature:'Natureza',report_group:'Grupo',cost_center_id:'Centro ID',cost_center_name:'Centro de custo',debit_cents:'Débitos',credit_cents:'Créditos',opening_cents:'Saldo inicial',balance_cents:'Saldo',closing_cents:'Saldo final',journal_ids:'Lançamentos de origem',result_cents:'Resultado',document_id:'Documento ID',series:'Série',model:'Modelo',partner_name:'Participante',direction:'Operação',cfop:'CFOP',total_cents:'Total',status:'Situação',title_id:'Título',kind:'Tipo',description:'Descrição',issue_date:'Emissão',due_date:'Vencimento',amount_cents:'Valor original',paid_cents:'Principal baixado',cash_cents:'Caixa',settlement_id:'Baixa',event:'Evento',consistent:'Consistente',settlement_ids:'Baixas',bank_ids:'Movimentos bancários',assets_cents:'Ativo',liabilities_cents:'Passivo',equity_cents:'Patrimônio líquido',unclosed_result_cents:'Resultado não encerrado',difference_cents:'Diferença',documents:'Documentos'};
for(const tax of ['icms','ipi','iss','pis','cofins','ibs','cbs']){labels[tax+'_cents']=tax.toUpperCase()+' declarado';labels[tax+'_base_cents']='Base '+tax.toUpperCase();labels[tax+'_informed_documents']='Documentos com '+tax.toUpperCase();}
const columns=computed(()=>[...new Set((result.value?.rows||[]).flatMap(Object.keys))].filter(k=>!['nature','account_id','cost_center_id'].includes(k)));const visible=computed(()=>(result.value?.rows||[]).slice((page.value-1)*50,page.value*50));
function parameters(){const p=new URLSearchParams({model:model.value,first_page:model.value==='internal'?1:firstPage.value,show_numbers:kind.value==='ledger'&&model.value==='prosoft-ledger-v1'&&showNumbers.value,cfop:kind.value.startsWith('fiscal-')&&kind.value!=='fiscal-assessments'?cfop.value:'',ncm:kind.value.startsWith('fiscal-')&&kind.value!=='fiscal-assessments'?ncm.value:'',start:start.value,end:end.value,query:searchable.value?query.value:'',status:statuses.value.length?status.value:'',direction:!accounting.value&&kind.value!=='fiscal-assessments'&&!fixedBook.value?direction.value:''});if(accounting.value&&account.value)p.set('account_id',account.value);if(accounting.value&&center.value)p.set('cost_center_id',center.value);return p;}
const filtersChanged=computed(()=>result.value&&result.value.parameters!==parameters().toString());
async function run(){
 if(busy.value||!state.companyId||state.contextBusy||!can(routine.value))return;
 if(!start.value||!end.value||start.value>end.value){error.value='Confira o intervalo: a data inicial deve ser anterior ou igual à final.';return;}
 closeOrigin();const seq=requests.begin();busy.value=true;error.value='';preview.value=false;
 const params=parameters().toString(),cid=state.companyId,url=scope(`/business-reports/${kind.value}?${params}`,cid);
 try{const r=await api(url);if(requests.current(seq)){result.value={...r,url,parameters:params};page.value=1;}}
 catch(e){if(requests.current(seq))error.value=e.message;}
 finally{if(requests.current(seq))busy.value=false;}
}
function display(k,v){if(v===null||v===undefined)return '—';if(k.endsWith('_cents'))return money(v);if(k==='date'||k.endsWith('_date'))return date(v);if(Array.isArray(v))return v.map(x=>'#'+x).join(', ');if(typeof v==='boolean')return v?'Sim':'Não';if(['status','kind','direction'].includes(k))return statusLabel(v);if(k==='report_group')return ({asset:'Ativo',liability:'Passivo',equity:'Patrimônio líquido',revenue:'Receita',expense:'Despesa'})[v]||'Não classificado';return v??'—';}
async function showOrigin(row,key){
 const report=result.value;if(!report)return;const seq=origins.begin(),cid=report.company_id;
 try{let entry;
 if(key==='ledger_id')entry={type:'Apuração',data:await api(scope(`/tax-ledgers/${row[key]}/report`,cid))};
 else if(key==='journal_id')entry={type:'Lançamento',data:await api(scope(`/journals/${row[key]}`,cid))};
 else if(key==='document_id')entry={type:'Documento',data:await api(scope(`/documents/${row[key]}/trace`,cid))};
 else if(key==='title_id'){const titles=await api(scope('/titles',cid));entry={type:'Título',data:titles.find(t=>t.id===row[key])};}
 if(origins.current(seq)&&result.value===report)origin.value=entry;
 }catch(e){if(origins.current(seq))notify(e.message,'error');}
}
function closeOrigin(){origins.invalidate();origin.value=null;}


</script>
<template><div class="view reports-view"><header class="view-heading"><div><div class="eyebrow">LIVROS E DEMONSTRATIVOS</div><h1>Livros e relatórios</h1><p>Filtros explícitos, valores conferíveis e acesso à origem.</p></div></header><details class="panel model-catalog"><summary>Catálogo dos modelos e evidências</summary><div class="table-scroll"><table><thead><tr><th>Modelo</th><th>Origem</th><th>Cobertura</th></tr></thead><tbody><tr v-for="m in areaModels" :key="m.id"><td>{{m.name}}</td><td>{{m.source}}</td><td>{{m.evidence}}<br>{{m.limitations}}</td></tr></tbody></table></div></details><form class="panel report-controls" @submit.prevent="run"><div class="form-grid three"><label>Relatório<select v-model="kind"><option v-for="(label,key) in kinds" :value="key" :key="key">{{label}}</option></select></label><label>Modelo de impressão<select v-model="model"><option value="internal">Modelo Escritura genérico</option><option v-for="m in selectedModels" :key="m.id" :value="m.id">{{m.name}}</option></select></label><label>Folha inicial<input type="number" v-model.number="firstPage" :disabled="model==='internal'" min="1" max="99999"/></label><label v-if="kind==='ledger'&&model==='prosoft-ledger-v1'"><span>Identificação dos lançamentos</span><span><input type="checkbox" v-model="showNumbers"/> Exibir números</span></label><label>Data inicial<DateInput v-model="start" required/></label><label>Data final<DateInput v-model="end" required/></label><label v-if="accounting">Conta<AccountSelect v-model="account" :disabled="!accounting" :accounts="data.accounts" empty-label="Todas"/></label><label v-if="accounting">Centro de custo<select v-model="center" :disabled="!accounting"><option value="">Todos</option><option v-for="c in data.centers" :value="c.id" :key="c.id">{{c.code}} · {{c.name}}</option></select></label><label v-if="searchable">Documento, participante ou histórico<input v-model="query" :disabled="!searchable"/></label><label v-if="statuses.length">Situação<select v-model="status" :disabled="!statuses.length"><option value="">Todas</option><option v-for="k in statuses" :key="k" :value="k">{{statusLabel(k)}}</option></select></label><label v-if="!accounting&&kind!=='fiscal-assessments'&&!fixedBook">Operação<select v-model="direction" :disabled="accounting"><option value="">Todas</option><template v-if="kind.startsWith('fiscal-')"><option value="incoming">Entrada fiscal</option><option value="outgoing">Saída fiscal</option></template><template v-else><option value="payable">A pagar</option><option value="receivable">A receber</option></template></select></label><template v-if="area==='fiscal'&&kind!=='fiscal-assessments'"><label>CFOP<input v-model="cfop" maxlength="4" :disabled="kind==='fiscal-assessments'"/></label><label>NCM<input v-model="ncm" maxlength="8" :disabled="kind==='fiscal-assessments'"/></label></template><button class="button primary" :disabled="busy||!state.companyId||state.contextBusy||!can(routine)">{{busy?'Consultando…':'Gerar relatório'}}</button></div><p v-if="fixedBook" class="report-note">Somente documentos escriturados de {{kind==='fiscal-entries'?'entrada':'saída'}}. Situação e operação são fixas neste livro.</p><p v-if="kind==='fiscal-assessments'" class="report-note">O intervalo seleciona competências mensais inclusivas, sem filtros por documento.</p><p v-if="selectedModel" class="report-note">{{selectedModel.evidence}} {{selectedModel.limitations}}</p></form><p v-if="error" class="message error" role="alert">{{error}}</p><section v-if="result" class="panel report-output"><header class="panel-heading"><div><h2>{{result.title||kinds[result.kind]}}</h2><p>{{result.company_name}} · {{date(result.start)}} a {{date(result.end)}}</p></div><div class="actions no-print"><a class="button outline" v-allow="[routine,'export']" :href="reportFileUrl(result.url,'csv')" download>Exportar CSV</a><a v-allow="[routine,'export']" class="button outline" :href="reportFileUrl(result.url,'xlsx')" download>Excel</a><a v-allow="[routine,'export']" class="button outline" :href="reportFileUrl(result.url,'pdf')" download>PDF</a><button class="button" v-if="can(routine,'print')" @click="preview=!preview">{{preview?'Ocultar prévia':'Visualizar PDF'}}</button></div></header><p v-if="filtersChanged" class="message subtle" role="status">Filtros alterados. Gere novamente para aplicá-los. A prévia e as exportações usam os filtros do relatório exibido.</p><ReportPdfPreview v-if="preview&&can(routine,'print')" :key="result.url" :url="reportFileUrl(result.url,'pdf',true)" :title="result.title||kinds[result.kind]" @close="preview=false"/><p class="report-note">{{result.scope_note}}</p><div class="summary-strip"><div v-for="(value,key) in result.totals" :key="key"><span>{{labels[key]||key}}</span><strong>{{display(key,value)}}</strong></div></div><div class="table-scroll"><table><thead><tr><th v-for="key in columns" :key="key">{{labels[key]||key}}</th></tr></thead><tbody><tr v-for="(r,i) in visible" :key="i"><td v-for="key in columns" :key="key" :class="{'right money':key.endsWith('_cents')}"><button v-if="['journal_id','document_id','title_id','ledger_id'].includes(key)&&r[key]" class="text-button" @click="showOrigin(r,key)">#{{r[key]}}</button><span v-else-if="key==='journal_ids'" class="actions"><button v-for="id in r[key]" :key="id" class="text-button" @click="showOrigin({journal_id:id},'journal_id')">#{{id}}</button></span><span v-else>{{display(key,r[key])}}</span></td></tr></tbody></table></div><footer class="table-footer no-print"><span>{{result.rows.length}} linhas · página {{page}} · totais abrangem todas as linhas</span><div class="actions"><button class="button small" @click="page--" :disabled="page===1">Anterior</button><button class="button small" @click="page++" :disabled="page*50>=result.rows.length">Próxima</button></div></footer><p v-if="result.rows.length>50" class="message subtle no-print">Impressão e CSV incluem todas as linhas.</p></section><BaseModal v-if="origin" :title="origin.type+' de origem'" wide @close="closeOrigin"><div v-if="originRecord"><template v-if="origin.type==='Apuração'"><p>{{origin.data.scope_note}}</p><a v-allow="['fiscal.assessments','export']" class="button" :href="`/api${scope(`/tax-ledgers/${origin.data.ledger_id}/report`,result.company_id)}?format=pdf`" download>PDF da memória</a><pre>{{JSON.stringify(origin.data.totals,null,2)}}</pre></template><dl class="origin-summary"><dt>Documento</dt><dd>{{originRecord.number||originRecord.document||'—'}}</dd><dt>Data</dt><dd>{{date(originRecord.date||originRecord.posting_date||originRecord.issue_date)}}</dd><dt>Histórico / participante</dt><dd>{{originRecord.history||originRecord.description||originRecord.partner_name}}</dd><dt>Valor</dt><dd>{{money(originRecord.total_cents??originRecord.amount_cents)}}</dd></dl><div v-if="originRecord.lines" class="table-scroll"><table><thead><tr><th>Conta</th><th>Centro</th><th>Débito</th><th>Crédito</th></tr></thead><tbody><tr v-for="line in originRecord.lines" :key="line.id"><td>{{line.access_code}} · {{line.account_name}}</td><td>{{line.cost_center_name||'—'}}</td><td>{{money(line.debit_cents)}}</td><td>{{money(line.credit_cents)}}</td></tr></tbody></table></div><div v-if="originRecord.settlements" class="table-scroll"><p>Saldo atual: <strong>{{money(originRecord.balance_cents)}}</strong></p><table><thead><tr><th>Baixa</th><th>Principal</th><th>Caixa</th><th>Situação</th></tr></thead><tbody><tr v-for="s in originRecord.settlements" :key="s.id"><td>{{date(s.date)}}</td><td>{{money(s.amount_cents)}}</td><td>{{money(s.cash_cents)}}</td><td>{{s.reversed_at?'Estornada':'Ativa'}}</td></tr></tbody></table></div><div v-if="origin.data.titles" class="table-scroll"><table><thead><tr><th>Título</th><th>Vencimento</th><th>Valor</th><th>Saldo</th></tr></thead><tbody><tr v-for="t in origin.data.titles" :key="t.id"><td>{{t.description}}</td><td>{{date(t.due_date)}}</td><td>{{money(t.amount_cents)}}</td><td>{{money(t.balance_cents)}}</td></tr></tbody></table></div></div><template #footer><button class="button" @click="closeOrigin">Fechar</button></template></BaseModal></div></template>
